/bin/bash -lc "python - <<'PY'
import inspect
from bioblend.galaxy.histories import HistoryClient
print([n for n in dir(HistoryClient) if 'histor' in n.lower() or 'copy' in n.lower()])
for n in dir(HistoryClient):
    if 'copy' in n.lower() or 'create' in n.lower():
        try: print(n, inspect.signature(getattr(HistoryClient,n)))
        except Exception: pass
PY"

/bin/bash -lc "python - <<'PY'
import inspect
from bioblend.galaxy.histories import HistoryClient
print([n for n in dir(HistoryClient) if 'histor' in n.lower() or 'copy' in n.lower()])
for n in dir(HistoryClient):
    if 'copy' in n.lower() or 'create' in n.lower():
        try: print(n, inspect.signature(getattr(HistoryClient,n)))
        except Exception: pass
PY"

